<?php
declare(strict_types=1);$active_module='inventory';require_once __DIR__.'/layout.php';require_once __DIR__.'/../config/i18n.php';$u=$supplier_user;$pdo=db();$propertyId=(int)($_GET['property']??0);$planFilter=(int)($_GET['plan']??0);$planFilterName='';$properties=$pdo->prepare('SELECT id,name,property_type FROM properties WHERE supplier_id=? AND status IN (\'draft\',\'active\') ORDER BY name');$properties->execute([$u['supplier_id']]);$properties=$properties->fetchAll();if(!$propertyId&&$properties)$propertyId=(int)$properties[0]['id'];$pt='hotel';foreach($properties as $pp){if((int)$pp['id']===$propertyId){$pt=$pp['property_type'];break;}}$tt=panel_link_tooltips();$editBase=($pt==='hotel'?'/nexustraveltech/tedarikci/otel-detay':'/nexustraveltech/tedarikci/villa-detay').'?product='.$propertyId.'#sec-04';$rooms=[];$rates=[];if($propertyId){$q=$pdo->prepare('SELECT id,name FROM room_types WHERE property_id=? AND status=\'active\' ORDER BY name');$q->execute([$propertyId]);$rooms=$q->fetchAll();$q=$pdo->prepare('SELECT id,name,currency,board_type,free_cancel_before_days,cancel_fee_percent,cancellation_policy FROM rate_plans WHERE property_id=? AND status=\'active\' ORDER BY name');$q->execute([$propertyId]);$rates=$q->fetchAll();}if($planFilter>0){$planOk=false;foreach($rates as $rr){if((int)$rr['id']===$planFilter){$planOk=true;$planFilterName=(string)$rr['name'];break;}}if(!$planOk){$planFilter=0;$planFilterName='';}}$notice='';$error='';if($_SERVER['REQUEST_METHOD']==='POST'){if(($_POST['action']??'')==='policy'){$rpId=(int)($_POST['rate_plan_id']??0);$q=$pdo->prepare('SELECT id FROM rate_plans WHERE id=? AND property_id=?');$q->execute([$rpId,$propertyId]);if(!$q->fetch())$error='Fiyat planı bulunamadı.';else{$pdo->prepare('UPDATE rate_plans SET free_cancel_before_days=?,cancel_fee_percent=?,cancellation_policy=? WHERE id=?')->execute([($_POST['free_cancel_before_days']??'')!==''?(int)$_POST['free_cancel_before_days']:null,max(0,(float)str_replace(',','.',$_POST['cancel_fee_percent']??0)),trim((string)($_POST['cancellation_policy']??''))?:null,$rpId]);$notice='İptal politikası güncellendi.';}}$room=(int)($_POST['room_type_id']??0);$rate=(int)($_POST['rate_plan_id']??0);$from=$_POST['from']??'';$to=$_POST['to']??'';$allotment=max(0,(int)($_POST['allotment']??0));$price=max(0,(float)str_replace(',','.',$_POST['base_price']??0));$min=max(1,(int)($_POST['min_stay']??1));$stop=isset($_POST['stop_sale']);if(!$room||!$rate||!$from||!$to||$from>$to)$error='Oda, fiyat planı ve tarih aralığını kontrol edin.';else{try{$pdo->beginTransaction();$date=new DateTimeImmutable($from);$end=new DateTimeImmutable($to);$up=$pdo->prepare('INSERT INTO inventory_calendar(room_type_id,rate_plan_id,stay_date,allotment,sold,base_price,min_stay,stop_sale) VALUES (?,?,?,?,0,?,?,?) ON CONFLICT(room_type_id,rate_plan_id,stay_date) DO UPDATE SET allotment=EXCLUDED.allotment,base_price=EXCLUDED.base_price,min_stay=EXCLUDED.min_stay,stop_sale=EXCLUDED.stop_sale');for(;$date<=$end;$date=$date->modify('+1 day'))$up->execute([$room,$rate,$date->format('Y-m-d'),$allotment,$price,$min,$stop]);$pdo->commit();$notice='Fiyat ve kontenjan takvimi güncellendi.';}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$error='Takvim kaydedilemedi.';}}}$calendar=[];if($rooms&&$rates){$q=$pdo->prepare('SELECT i.*,r.name room_name,p.name rate_name,p.currency FROM inventory_calendar i JOIN room_types r ON r.id=i.room_type_id JOIN rate_plans p ON p.id=i.rate_plan_id WHERE r.property_id=? AND i.stay_date BETWEEN current_date AND current_date+30' . ($planFilter>0?' AND i.rate_plan_id='.(int)$planFilter:'') . ' ORDER BY i.stay_date,r.name');$q->execute([$propertyId]);$calendar=$q->fetchAll();}
if(($_GET['export']??'')==='csv'){header('Content-Type:text/csv;charset=utf-8');header('Content-Disposition:attachment;filename="fiyat-kontenjan-'.date('Ymd').'.csv"');$out=fopen('php://output','w');fwrite($out,"\xEF\xBB\xBF");fputcsv($out,['Tarih','Oda/Birim','Fiyat Planı','Para Birimi','Fiyat','Kontenjan','Satış','Doluluk %','Durum']);foreach($calendar as $c){$occ=((int)$c['allotment']>0&&!$c['stop_sale'])?(int)round(((int)$c['sold']/(int)$c['allotment'])*100):null;fputcsv($out,[$c['stay_date'],$c['room_name'],$c['rate_name'],$c['currency'],number_format((float)$c['base_price'],2,'.',''),$c['allotment'],$c['sold'],$occ!==null?$occ.'%':'',!empty($c['stop_sale'])?'KAPALI':'Açık']);}fclose($out);exit;}
supply_start('Fiyat & kontenjan',$active_module);?><section class="page-intro"><p>Canlı satışa açacağınız fiyat, kontenjan, minimum konaklama ve stop-sale kurallarını yönetin.</p></section><?php if($notice):?><p class="save-success">✓ <?=htmlspecialchars($notice)?></p><?php endif;?><?php if($error):?><p class="login-error"><?=htmlspecialchars($error)?></p><?php endif;?><form method="get" class="supply-form"><label>Ürün<select name="property" onchange="this.form.submit()"><?php foreach($properties as $p):?><option value="<?=$p['id']?>" <?=$p['id']==$propertyId?'selected':''?>><?=htmlspecialchars($p['name'])?></option><?php endforeach;?></select></label></form><?php if($rooms&&$rates):?><form method="post" class="supply-form"><h2 id="kural-uygula">Takvim kuralı uygula</h2><div class="form-row"><label>Oda / birim<select name="room_type_id"><?php foreach($rooms as $r):?><option value="<?=$r['id']?>"><?=htmlspecialchars($r['name'])?></option><?php endforeach;?></select></label><label>Fiyat planı<select name="rate_plan_id"><?php foreach($rates as $r):?><option value="<?=$r['id']?>" <?= (int)$planFilter===(int)$r['id']?'selected':'' ?>><?=htmlspecialchars($r['name'])?> · <?=htmlspecialchars($r['currency'])?></option><?php endforeach;?></select></label></div><div class="form-row"><label>Başlangıç<input type="date" name="from" value="<?=date('Y-m-d')?>"></label><label>Bitiş<input type="date" name="to" value="<?=date('Y-m-d',strtotime('+30 days'))?>"></label></div><div class="form-row"><label>Kontenjan<input type="number" name="allotment" min="0" value="0"></label><label>Gecelik fiyat<input type="number" name="base_price" min="0" step="0.01"></label><label>Min. konaklama<input type="number" name="min_stay" min="1" value="1"></label></div><label><input type="checkbox" name="stop_sale"> Satışı kapat</label><button>Takvime uygula →</button></form><section class="next-module"><h2>Önümüzdeki 30 gün<?php if($planFilter>0):?><small style="font-weight:400;color:#64716d"> · yalnızca: <?=htmlspecialchars($planFilterName)?> <a href="?property=<?=(int)$propertyId?>" style="color:#b26a00;text-decoration:none;border-bottom:1px dotted #b26a00">tümü göster</a></small><?php endif;?> <a class="csv-export-btn" href="<?=htmlspecialchars('?property='.$propertyId.'&export=csv')?>" title="Görünen 30 günlük listeyi CSV olarak indir">CSV indir ↓</a></h2><?php foreach($calendar as $c):$occPct=((int)$c['allotment']>0&&!$c['stop_sale'])?(int)round(((int)$c['sold']/(int)$c['allotment'])*100):null;$occStyle=$occPct!==null&&$occPct>90?'background:#ffe0d6;border-left:3px solid #b0301a;padding:6px 10px;border-radius:6px':($occPct!==null&&$occPct>=70?'background:#fff3d6;border-left:3px solid #b26a00;padding:6px 10px;border-radius:6px':'');?><p<?= $occStyle?' style="'.$occStyle.'"':'' ?>><b><?=htmlspecialchars($c['stay_date'])?></b> · <?=htmlspecialchars($c['room_name'])?> · <?=number_format((float)$c['base_price'],2)?> <?=htmlspecialchars($c['currency'])?> · kontenjan <?= (int)$c['allotment']?> / satış <?= (int)$c['sold']?><?= $occPct!==null?' · <b style="color:'.($occPct>90?'#b0301a':($occPct>=70?'#b26a00':'#2e7d32')).'">doluluk '.$occPct.'%</b>':'' ?><?php $rowUrl='/nexustraveltech/tedarikci/fiyat-kontenjan.php?property='.(int)$propertyId.'#kural-uygula';$rowShort='fiyat-kontenjan · #kural-uygula'; if($c['stop_sale']):?> · KAPALI <a title="<?=htmlspecialchars($tt['row_inspect'])?>" href="<?=htmlspecialchars('?property='.$propertyId.'#kural-uygula')?>" style="color:#b26a00;text-decoration:none;border-bottom:1px dotted #b26a00">İncele →</a><?php else:?> <a title="<?=htmlspecialchars($tt['row_view'])?>" href="<?=htmlspecialchars('?property='.$propertyId.'#kural-uygula')?>" style="color:#4a6d8c;text-decoration:none;border-bottom:1px dotted #4a6d8c">Gör →</a><?php endif;?> <button type="button" class="ical-copy-btn" data-copy="<?=htmlspecialchars($rowUrl)?>" title="<?=htmlspecialchars($rowUrl)?>" style="font-size:10px;padding:1px 5px;vertical-align:middle"><span class="copy-short">⧉ <?=htmlspecialchars($rowShort)?></span><span class="copy-full" hidden>⧉</span></button></p><?php endforeach;?></section>
<section class="next-module"><h2>İptal politikası</h2><p class="muted">İade, fiyat planı başına otomatik hesaplanır: check-in'e N gün kala ücretsiz iptal; sonrası iptal ücreti (%) düşülür.</p><?php foreach($rates as $r):?><form method="post" class="supply-form"><input type="hidden" name="csrf" value="<?=htmlspecialchars($_SESSION['supplier_csrf'])?>"><input type="hidden" name="action" value="policy"><input type="hidden" name="rate_plan_id" value="<?=$r['id']?>"><p><b><?=htmlspecialchars($r['name'])?></b></p><div class="form-row"><label>Ücretsiz iptal: check-in kaç gün öncesine kadar?<input type="number" name="free_cancel_before_days" min="0" value="<?=$r['free_cancel_before_days']!==null?(int)$r['free_cancel_before_days']:''?>"></label><label>İptal ücreti % (pencere sonrası)<input type="number" name="cancel_fee_percent" min="0" max="100" step="0.01" value="<?=htmlspecialchars((string)$r['cancel_fee_percent'])?>"></label></div><input name="cancellation_policy" placeholder="Politika metni (opsiyonel)" value="<?=htmlspecialchars((string)($r['cancellation_policy']??''))?>"><button>Politikayı kaydet</button></form><?php endforeach;?></section><?php else:?><p class="login-error">Bu ürün için önce oda/birim ve fiyat planı tanımlanmalıdır. <a title="<?=htmlspecialchars($pt==='hotel'?$tt['rooms_edit']:$tt['units_edit'])?>" href="<?=htmlspecialchars($editBase)?>" style="color:#b3261e;text-decoration:none;border-bottom:1px dotted #b3261e">Doldur →</a></p><?php endif;?><script>function fallbackCopy(text){var ta=document.createElement('textarea');ta.value=text;ta.style.position='fixed';ta.style.opacity='0';document.body.appendChild(ta);ta.select();try{document.execCommand('copy')}catch(e){}document.body.removeChild(ta)}document.querySelectorAll('.ical-copy-btn').forEach(function(b){if(!b.title)b.title=b.getAttribute('data-copy')||'';var origHTML=b.innerHTML;b.addEventListener('click',function(){var url=this.getAttribute('data-copy'),btn=this;function done(){var mob=window.innerWidth<601;btn.textContent=mob?'✓':'Kopyalandı!';btn.classList.add('copied');setTimeout(function(){btn.innerHTML=origHTML;btn.classList.remove('copied')},2000)}if(navigator.clipboard&&navigator.clipboard.writeText){navigator.clipboard.writeText(url).then(done).catch(function(){fallbackCopy(url);done()})}else{fallbackCopy(url);done()}})});</script><?php supply_end(); ?>
